def split_csv(line):
    """
    Parse a CSV line and return its fields as a list of strings.
    Returns None if the line is malformed.
    """
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - we've completed a field
            break

        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Potential end of quoted field or escaped quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents one quote character
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i == len(line) or line[i] == ',':
                            fields.append(field)
                            if i < len(line):
                                i += 1  # Skip the comma
                            break
                        else:
                            # Malformed: closing quote not followed by comma or EOL
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field - runs to next comma or EOL
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

